<script setup lang="ts">
import { ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, problem } from '../api'
import type { ApiProblem, Dashboard } from '../types'
import { date, pretty, query, sourceNames, stateNames } from '../workbench'
import AsyncState from '../components/AsyncState.vue'
import SummaryPanel from '../components/SummaryPanel.vue'
const route = useRoute(), router = useRouter(), data = ref<Dashboard | null>(null), loading = ref(true), error = ref<ApiProblem | null>(null), source = ref(query(route.query.source) || 'REAL_EXTERNAL')
let generation = 0
async function load() { const current = ++generation; loading.value = true; error.value = null; data.value = null; try { const result = await api.dashboard(source.value); if (current === generation) data.value = result } catch (e) { if (current === generation) error.value = problem(e) } finally { if (current === generation) loading.value = false } }
function change() { void router.replace({ query: { source: source.value } }) }
watch(() => route.fullPath, () => { source.value = query(route.query.source) || 'REAL_EXTERNAL'; void load() }, { immediate: true })
</script>
<template><div class="page-heading"><div><div class="eyebrow">DASHBOARD / RUN EVIDENCE</div><h1>运行概览</h1><p>最近运行可追溯到独立报告，质量概览按来源选择明确的单次运行。</p></div><ElButton @click="load">刷新概览</ElButton></div><section class="panel"><div class="panel-heading"><h2>关键指标范围</h2><label class="compact-label">来源<select v-model="source" @change="change"><option value="REAL_EXTERNAL">真实外部连接声明</option><option value="PROTOCOL_DOUBLE">协议替身</option><option value="MOCK">模拟</option><option value="ALL">全部来源（最近一次）</option></select></label></div><AsyncState :loading="loading" :error="error" @retry="load"><div v-if="data" class="panel-body"><p class="small muted scope-note">此处仅展示所选来源下最近一次运行，不跨批次平均；真实外部连接声明仍须有实际模型证据。</p><template v-if="data.summary"><SummaryPanel :summary="data.summary" /><RouterLink class="text-link small" :to="{ path: '/reports', query: { run_id: data.selected_run_id } }">进入本次报告 →</RouterLink></template><div v-else class="state-panel"><div class="empty-mark">◫</div><strong>所选来源暂无运行</strong><p>切换来源查看已有模拟记录，或在实验页启动新运行。</p><RouterLink class="text-link" to="/experiments">前往实验</RouterLink></div><details class="raw-detail"><summary>来源范围和记录计数</summary><pre>{{ pretty(data.source_scope) }}</pre></details></div></AsyncState></section><section v-if="data && !loading && !error" class="panel section-gap"><div class="panel-heading"><h2>最近运行 <span class="count-label">全部来源分别标识</span></h2><RouterLink class="text-link small" to="/experiments">管理实验 →</RouterLink></div><AsyncState :empty="!data.recent_runs.length" empty-title="尚无运行记录" empty-text="先创建数据集、配置连接并启动实验。"><template #empty-action><RouterLink class="text-link" to="/experiments">创建实验</RouterLink></template><div class="table-scroll"><table><thead><tr><th>运行</th><th>来源</th><th>状态</th><th>冻结总数</th><th>报告</th></tr></thead><tbody><tr v-for="run in data.recent_runs" :key="run.id"><td><span class="mono small">{{ run.id.slice(0, 8) }}</span><p class="table-subtext">{{ date(run.created_at) }} · 实验 #{{ run.experiment_id }}</p></td><td><ElTag size="small" :type="run.source_type === 'REAL_EXTERNAL' ? 'info' : 'warning'">{{ sourceNames[run.source_type] || run.source_type }}</ElTag></td><td>{{ stateNames[run.status] || run.status }}</td><td class="number">{{ run.total_cases }}</td><td><RouterLink class="text-link" :to="{ path: '/reports', query: { run_id: run.id, score_set_id: run.score_set_id } }">查看报告 →</RouterLink></td></tr></tbody></table></div></AsyncState></section></template>
